CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.LinearAlgebra.AlmostMathieu","name":"GRWTSK.LinearAlgebra.AlmostMathieu.transfer.eq_1","type":"∀ (E α coupling θ : ℝ) (n : ℤ),\n  GRWTSK.LinearAlgebra.AlmostMathieu.transfer E α coupling θ n =\n    GRWTSK.LinearAlgebra.SchrodingerTransfer.schrodingerTransfer E\n      (GRWTSK.LinearAlgebra.AlmostMathieu.potential α coupling θ n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.LinearAlgebra.AlmostMathieu","name":"GRWTSK.LinearAlgebra.AlmostMathieu.det_transfer","type":"∀ (E α coupling θ : ℝ) (n : ℤ), (GRWTSK.LinearAlgebra.AlmostMathieu.transfer E α coupling θ n).det = 1"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.LinearAlgebra.AlmostMathieu","name":"GRWTSK.LinearAlgebra.AlmostMathieu.det_one_does_not_bound_trace","type":"(GRWTSK.LinearAlgebra.AlmostMathieu.transfer 3 0 0 0 0).det = 1 ∧\n  2 < |(GRWTSK.LinearAlgebra.AlmostMathieu.transfer 3 0 0 0 0).trace|"}
