CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.LinearAlgebra.AlmostMathieu","name":"GRWTSK.LinearAlgebra.AlmostMathieu.recurrence_iff_transfer","type":"∀ (E α coupling θ : ℝ) (n : ℤ) (previous current next : ℝ),\n  next + previous + GRWTSK.LinearAlgebra.AlmostMathieu.potential α coupling θ n * current = E * current ↔\n    GRWTSK.LinearAlgebra.SchrodingerTransfer.rawState next current =\n      (GRWTSK.LinearAlgebra.AlmostMathieu.transfer E α coupling θ n).mulVec\n        (GRWTSK.LinearAlgebra.SchrodingerTransfer.rawState current previous)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.LinearAlgebra.AlmostMathieu","name":"GRWTSK.LinearAlgebra.AlmostMathieu.potential.eq_1","type":"∀ (α coupling θ : ℝ) (n : ℤ),\n  GRWTSK.LinearAlgebra.AlmostMathieu.potential α coupling θ n = 2 * coupling * Real.cos (2 * Real.pi * α * ↑n + θ)"}
