CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.LaplaceTransform.ExponentialThreshold","name":"GRWTSK.RiemannHypothesis.CCC.exponential_boundary_control","type":"(Continuous fun u => Real.exp (u / 2)) ∧\n  MeasureTheory.IntegrableOn (fun u => Real.exp (-2 * u) * Real.exp (u / 2) ^ 2) (Set.Ici 0) MeasureTheory.volume ∧\n    ¬MeasureTheory.IntegrableOn (fun u => Real.exp (-u) * Real.exp (u / 2) ^ 2) (Set.Ici 0) MeasureTheory.volume"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.LaplaceTransform.ExponentialThreshold","name":"GRWTSK.RiemannHypothesis.CCC.exponential_boundary_control._simp_1_2","type":"∀ {α : Type u_1} {ε' : Type u_4} {mα : MeasurableSpace α} {s : Set α} {μ : MeasureTheory.Measure α}\n  [inst : TopologicalSpace ε'] [inst_1 : ESeminormedAddMonoid ε'] {C : ε'},\n  autoParam (‖C‖ₑ ≠ ⊤) MeasureTheory.integrableOn_const_iff._auto_1 →\n    MeasureTheory.IntegrableOn (fun x => C) s μ = (‖C‖ₑ = 0 ∨ μ s < ⊤)"}
