CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.MertensPrimitive","name":"GRWTSK.RiemannHypothesis.CCC.complete_gram_split","type":"∀ {ι : Type u_1} [inst : DecidableEq ι] (S : Finset ι) (c : ι → ℝ) (H : ι → ι → ℝ),\n  ∑ m ∈ S, ∑ n ∈ S, c m * c n * H m n =\n    ∑ m ∈ S, c m ^ 2 * H m m + ∑ m ∈ S, ∑ n ∈ S, if m ≠ n then c m * c n * H m n else 0"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.MertensPrimitive","name":"GRWTSK.RiemannHypothesis.CCC.cross_poly_iff_energy_poly","type":"(∀ (T : ℝ), 0 ≤ T → pickupEnergy T = pickupDiagonal T + pickupCross T) →\n  (∀ (T : ℝ), 0 ≤ T → 0 ≤ pickupDiagonal T ∧ pickupDiagonal T ≤ 2 * T ^ 2) → (PickupCrossPoly ↔ PickupEnergyPoly)"}
