CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_finite_atom_integrals","type":"∀ {T : ℝ},\n  0 ≤ T → wholePickup T = ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * ∫ (u : ℝ) in 0..T, pickupAtomVelocity n u"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickup_exp_negative_log_half","type":"∀ {n : ℕ}, 1 ≤ n → Real.exp (-Real.log ↑n / 2) = (√↑n)⁻¹"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_closed_prefix_rpow","type":"∀ {T : ℝ},\n  0 ≤ T → wholePickup T = 2 * ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * (↑n ^ (-(1 / 2)) - Real.exp (-T / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupEnergy_eq_diagonal_add_cross","type":"∀ {T : ℝ}, 0 ≤ T → pickupEnergy T = pickupDiagonal T + pickupCross T"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_closed_prefix","type":"∀ {T : ℝ}, 0 ≤ T → wholePickup T = 2 * ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * ((√↑n)⁻¹ - Real.exp (-T / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupResponse.eq_1","type":"∀ (n : ℕ) (u : ℝ), pickupResponse n u = if Real.log ↑n ≤ u then 2 * ((√↑n)⁻¹ - Real.exp (-u / 2)) else 0"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.mertensPrefix_fixed_inventory","type":"∀ {u T : ℝ},\n  u ≤ T → mertensPrefix (Real.exp u) = ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, if Real.log ↑n ≤ u then moebiusReal n else 0"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickup_inverse_sqrt_eq_negative_half","type":"∀ (n : ℕ), (√↑n)⁻¹ = ↑n ^ (-(1 / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupEnergy_eq_full_gram","type":"∀ {T : ℝ}, 0 ≤ T → pickupEnergy T = pickupFullGram T"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupResponse_at_event","type":"∀ {n : ℕ}, 1 ≤ n → pickupResponse n (Real.log ↑n) = 0"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickup_log_le_iff_closed_cutoff","type":"∀ {n : ℕ}, 1 ≤ n → ∀ (u : ℝ), Real.log ↑n ≤ u ↔ n ≤ ⌊Real.exp u⌋₊"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"definition","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupAtomVelocity","type":"ℕ → ℝ → ℝ"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_fixed_inventory","type":"∀ {u T : ℝ}, 0 ≤ u → u ≤ T → wholePickup u = ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * pickupResponse n u"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupResponse_continuous","type":"∀ {n : ℕ}, 1 ≤ n → Continuous (pickupResponse n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickup_negative_half_integral","type":"∀ (a b : ℝ), ∫ (u : ℝ) in a..b, Real.exp (-u / 2) = 2 * (Real.exp (-a / 2) - Real.exp (-b / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupAtomVelocity_integral","type":"∀ {n : ℕ},\n  1 ≤ n → ∀ {T : ℝ}, Real.log ↑n ≤ T → ∫ (u : ℝ) in 0..T, pickupAtomVelocity n u = 2 * ((√↑n)⁻¹ - Real.exp (-T / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupResponse_product_intervalIntegrable","type":"∀ {m n : ℕ},\n  1 ≤ m →\n    1 ≤ n → ∀ (a b : ℝ), IntervalIntegrable (fun u => pickupResponse m u * pickupResponse n u) MeasureTheory.volume a b"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupAtomVelocity_measurable","type":"∀ (n : ℕ), Measurable (pickupAtomVelocity n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_closed_prefix_flux","type":"∀ {T : ℝ},\n  0 ≤ T →\n    wholePickup T =\n      2 * ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * (√↑n)⁻¹ - 2 * Real.exp (-T / 2) * mertensPrefix (Real.exp T)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupAtomVelocity.eq_1","type":"∀ (n : ℕ) (u : ℝ), pickupAtomVelocity n u = if Real.log ↑n ≤ u then Real.exp (-u / 2) else 0"}
CCC_DECL::{"axioms":["propext"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupAtomVelocity._proof_1","type":"(1 + 1).AtLeastTwo"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_response_sum","type":"∀ {T : ℝ}, 0 ≤ T → wholePickup T = ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * pickupResponse n T"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.pickupVelocity_fixed_inventory","type":"∀ {u T : ℝ}, u ≤ T → pickupVelocity u = ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n * pickupAtomVelocity n u"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.mertensPrefix.eq_1","type":"∀ (x : ℝ), mertensPrefix x = ∑ n ∈ Finset.Icc 1 ⌊x⌋₊, moebiusReal n"}
CCC_DECL::{"axioms":["propext","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.FiniteResponseSum","name":"GRWTSK.RiemannHypothesis.CCC.wholePickup_closed_prefix_flux._simp_1_1","type":"∀ {ι : Type u_1} {R : Type u_4} [inst : NonUnitalNonAssocSemiring R] (s : Finset ι) (f : ι → R) (a : R),\n  ∑ i ∈ s, f i * a = (∑ i ∈ s, f i) * a"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.Inequalities.ExponentialDiagonal","name":"GRWTSK.RiemannHypothesis.CCC.DiagonalAffineAlgebra.sharp_diagonal_le_quadratic","type":"∀ (T : ℝ), 2 * T ^ 2 - 8 * T + 16 * (1 - Real.exp (-T / 2)) ≤ 2 * T ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"definition","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison","type":"ℝ → ℝ → ℝ"}
CCC_DECL::{"axioms":["propext","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range._proof_1_4","type":"∀ (N k : ℕ), ¬1 ≤ k + 1 → False"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.pickup_diagonal_density_le","type":"∀ {u T : ℝ},\n  0 ≤ u →\n    u ≤ T →\n      ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n ^ 2 * pickupResponse n u ^ 2 ≤ 4 * u - 8 + 8 * Real.exp (-u / 2)"}
CCC_DECL::{"axioms":["propext"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison._proof_2","type":"(1 + 1).AtLeastTwo"}
CCC_DECL::{"axioms":["propext","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range._proof_1_5","type":"∀ (N k : ℕ), k < N → ¬k + 1 ≤ N → False"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.pickupDiagonal_quadratic_bound","type":"∀ {T : ℝ}, 0 ≤ T → 0 ≤ pickupDiagonal T ∧ pickupDiagonal T ≤ 2 * T ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.pickup_response_square_sum_cutoff","type":"∀ {u T : ℝ},\n  u ≤ T →\n    ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, pickupResponse n u ^ 2 = ∑ n ∈ Finset.Icc 1 ⌊Real.exp u⌋₊, pickupResponse n u ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_atom","type":"∀ {u : ℝ} {n : ℕ}, 1 ≤ n → n ≤ ⌊Real.exp u⌋₊ → pickupResponse n u ^ 2 = diagonalComparison u ↑n"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range._simp_1_1","type":"∀ {n m : ℕ}, (m ∈ Finset.range n) = (m < n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_eq_below_one","type":"∀ {u x : ℝ}, x ≤ 1 → diagonalComparison u x = 4 * (1 - Real.exp (-u / 2)) ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_time_integral","type":"∀ (T : ℝ), ∫ (u : ℝ) in 0..T, 4 * u - 8 + 8 * Real.exp (-u / 2) = 2 * T ^ 2 - 8 * T + 16 * (1 - Real.exp (-T / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sqrt_exp","type":"∀ (u : ℝ), √(Real.exp u) = Real.exp (u / 2)"}
CCC_DECL::{"axioms":["propext","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range._proof_1_6","type":"∀ (N k : ℕ), ¬k + 1 - 1 = k → False"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison.eq_1","type":"∀ (u x : ℝ), diagonalComparison u x = 4 * ((√(max 1 x))⁻¹ - Real.exp (-u / 2)) ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.pickupDiagonal_eq_integral_density","type":"∀ (T : ℝ),\n  pickupDiagonal T = ∫ (u : ℝ) in 0..T, ∑ n ∈ Finset.Icc 1 ⌊Real.exp T⌋₊, moebiusReal n ^ 2 * pickupResponse n u ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_nonneg","type":"∀ (u x : ℝ), 0 ≤ diagonalComparison u x"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_sum_le_integral","type":"∀ {u : ℝ},\n  0 ≤ u → ∑ n ∈ Finset.Icc 1 ⌊Real.exp u⌋₊, diagonalComparison u ↑n ≤ ∫ (x : ℝ) in 0..Real.exp u, diagonalComparison u x"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.moebiusReal_sq_le_one","type":"∀ (n : ℕ), moebiusReal n ^ 2 ≤ 1"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.pickupDiagonal_sharp_bound","type":"∀ {T : ℝ},\n  0 ≤ T →\n    0 ≤ pickupDiagonal T ∧\n      pickupDiagonal T ≤ 2 * T ^ 2 - 8 * T + 16 * (1 - Real.exp (-T / 2)) ∧\n        2 * T ^ 2 - 8 * T + 16 * (1 - Real.exp (-T / 2)) ≤ 2 * T ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_negative_half_sqrt","type":"∀ (u : ℝ), Real.exp (-u / 2) = (√(Real.exp u))⁻¹"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_antitone","type":"∀ {u : ℝ}, 0 ≤ u → AntitoneOn (diagonalComparison u) (Set.Icc 0 (Real.exp u))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_eq_above_one","type":"∀ {u x : ℝ}, 1 ≤ x → diagonalComparison u x = 4 * ((√x)⁻¹ - Real.exp (-u / 2)) ^ 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range","type":"∀ (N : ℕ) (f : ℕ → ℝ), ∑ n ∈ Finset.Icc 1 N, f n = ∑ k ∈ Finset.range N, f (k + 1)"}
CCC_DECL::{"axioms":["propext"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_time_integral._simp_1_1","type":"∀ {R : Type u_1} [inst : AddMonoidWithOne R] [CharZero R] (n : ℕ) [inst_2 : n.AtLeastTwo], (OfNat.ofNat n = 0) = False"}
CCC_DECL::{"axioms":["propext"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison._proof_1","type":"(3 + 1).AtLeastTwo"}
CCC_DECL::{"axioms":["propext","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range._proof_1_2","type":"∀ (N n : ℕ), 1 ≤ n ∧ n ≤ N → ¬n - 1 < N → False"}
CCC_DECL::{"axioms":["propext","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_sum_Icc_eq_range._proof_1_3","type":"∀ (n m : ℕ), n - 1 = m - 1 → 1 ≤ n → 1 ≤ m → ¬n = m → False"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonal_inverse_sqrt_integral","type":"∀ {u : ℝ}, 0 ≤ u → ∫ (x : ℝ) in 1..Real.exp u, (√x)⁻¹ = 2 * (Real.exp (u / 2) - 1)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_continuous","type":"∀ (u : ℝ), Continuous (diagonalComparison u)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.pickupDiagonal_le_sharp","type":"∀ {T : ℝ}, 0 ≤ T → pickupDiagonal T ≤ 2 * T ^ 2 - 8 * T + 16 * (1 - Real.exp (-T / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.GramDiagonalBound","name":"GRWTSK.RiemannHypothesis.CCC.diagonalComparison_integral","type":"∀ {u : ℝ}, 0 ≤ u → ∫ (x : ℝ) in 0..Real.exp u, diagonalComparison u x = 4 * u - 8 + 8 * Real.exp (-u / 2)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"definition","module":"GRWTSK.NumberTheory.Moebius.LaplaceTransform","name":"GRWTSK.RiemannHypothesis.CCC.pickupLaplaceDomain","type":"Set ℂ"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"definition","module":"GRWTSK.NumberTheory.Moebius.LaplaceTransform","name":"GRWTSK.RiemannHypothesis.CCC.signedPickupLaplace","type":"ℂ → ℂ"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupTriangle_time_integral","type":"∀ (z : ℂ) (t : ℝ),\n  0 < t →\n    ∫ (u : ℝ) in Set.Ioi 0, PickupInitialTransform.pickupTriangle z (t, u) = Complex.exp (-z * ↑t) * ↑(wholePickup t)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.mertensPrefix_laplace","type":"∀ {s : ℂ},\n  1 < s.re → ∫ (u : ℝ) in Set.Ioi 0, Complex.exp (-s * ↑u) * ↑(mertensPrefix (Real.exp u)) = 1 / (s * riemannZeta s)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.wholePickup_laplace","type":"∀ {z : ℂ},\n  1 / 2 < z.re →\n    ∫ (t : ℝ) in Set.Ioi 0, Complex.exp (-z * ↑t) * ↑(wholePickup t) = 1 / (z * (z + 1 / 2) * riemannZeta (z + 1 / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius.eq_1","type":"∀ (n : ℕ), PickupInitialTransform.complexMoebius n = ↑(moebiusReal n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius_summable","type":"∀ {s : ℂ}, 1 < s.re → LSeriesSummable PickupInitialTransform.complexMoebius s"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupTriangle_density_integral","type":"∀ {z : ℂ},\n  1 / 2 < z.re →\n    ∀ (u : ℝ),\n      0 < u →\n        ∫ (t : ℝ) in Set.Ioi 0, PickupInitialTransform.pickupTriangle z (t, u) =\n          z⁻¹ * (Complex.exp (-z * ↑u) * ↑(pickupVelocity u))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"definition","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupTriangle","type":"ℂ → ℝ × ℝ → ℂ"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.moebiusReal.eq_1","type":"∀ (n : ℕ), moebiusReal n = ↑(ArithmeticFunction.moebius n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.mertensPrefix_mellin","type":"∀ {s : ℂ}, 1 < s.re → ∫ (x : ℝ) in Set.Ioi 1, ↑(mertensPrefix x) * ↑x ^ (-(s + 1)) = 1 / (s * riemannZeta s)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupTriangle_measurable","type":"∀ (z : ℂ), Measurable (PickupInitialTransform.pickupTriangle z)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupTriangle_integrable","type":"∀ {z : ℂ},\n  1 / 2 < z.re →\n    MeasureTheory.Integrable (PickupInitialTransform.pickupTriangle z)\n      ((MeasureTheory.volume.restrict (Set.Ioi 0)).prod (MeasureTheory.volume.restrict (Set.Ioi 0)))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius_eq","type":"∀ (n : ℕ), PickupInitialTransform.complexMoebius n = ↑(ArithmeticFunction.moebius n)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius_LSeries","type":"∀ {s : ℂ}, 1 < s.re → LSeries PickupInitialTransform.complexMoebius s = 1 / riemannZeta s"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.initial_transform","type":"∀ {z : ℂ}, 1 / 2 < z.re → signedPickupLaplace z = 1 / (z * (z + 1 / 2) * riemannZeta (z + 1 / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupTriangle.eq_1","type":"∀ (z : ℂ) (p : ℝ × ℝ),\n  PickupInitialTransform.pickupTriangle z p =\n    {p | p.2 ≤ p.1}.indicator (fun p => Complex.exp (-z * ↑p.1) * ↑(pickupVelocity p.2)) p"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"definition","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius","type":"ℕ → ℂ"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius_prefix_bigO","type":"(fun n => ∑ k ∈ Finset.Icc 1 n, PickupInitialTransform.complexMoebius k) =O[Filter.atTop] fun n => ↑n ^ 1"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.signedPickupLaplace.eq_1","type":"∀ (z : ℂ), signedPickupLaplace z = ∫ (t : ℝ) in Set.Ioi 0, Complex.exp (-z * ↑t) * ↑(wholePickup t)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.complexMoebius_prefix","type":"∀ (x : ℝ), ∑ n ∈ Finset.Icc 1 ⌊x⌋₊, PickupInitialTransform.complexMoebius n = ↑(mertensPrefix x)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.DirichletLaplaceIdentity","name":"GRWTSK.RiemannHypothesis.CCC.PickupInitialTransform.pickupVelocity_laplace","type":"∀ {z : ℂ},\n  1 / 2 < z.re →\n    ∫ (u : ℝ) in Set.Ioi 0, Complex.exp (-z * ↑u) * ↑(pickupVelocity u) = 1 / ((z + 1 / 2) * riemannZeta (z + 1 / 2))"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.LaplaceTransform.PolynomialEnergy","name":"GRWTSK.RiemannHypothesis.CCC.integrableOn_tilt_of_polynomial_energy","type":"∀ {f : ℝ → ℝ},\n  Continuous f →\n    ∀ {C q : ℝ},\n      0 ≤ C →\n        (∀ (T : ℝ), 0 ≤ T → ∫ (u : ℝ) in 0..T, f u ^ 2 ≤ C * (1 + T) ^ q) →\n          ∀ {σ : ℝ},\n            0 < σ → MeasureTheory.IntegrableOn (fun u => Real.exp (-σ * u) * f u) (Set.Ioi 0) MeasureTheory.volume"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.LaplaceTransform.PolynomialEnergy","name":"GRWTSK.RiemannHypothesis.CCC.summable_exp_neg_mul_nat_add_rpow","type":"∀ (σ q : ℝ), 0 < σ → Summable fun n => Real.exp (-σ * ↑n) * (↑n + 2) ^ q"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.LaplaceTransform.PolynomialEnergy","name":"GRWTSK.RiemannHypothesis.CCC.tilted_block_norm_bound","type":"∀ {f : ℝ → ℝ},\n  Continuous f →\n    ∀ {C q σ : ℝ},\n      0 < σ →\n        (∀ (T : ℝ), 0 ≤ T → ∫ (u : ℝ) in 0..T, f u ^ 2 ≤ C * (1 + T) ^ q) →\n          ∀ (n : ℕ),\n            ∫ (u : ℝ) in Set.Icc (↑n) (↑n + 1), ‖Real.exp (-σ * u) * f u‖ ≤ Real.exp (-σ * ↑n) * (1 + C * (↑n + 2) ^ q)"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.Analysis.LaplaceTransform.Analytic","name":"GRWTSK.RiemannHypothesis.CCC.Laplace.transform_analytic","type":"∀ {Ω : Type u_1} [inst : MeasurableSpace Ω] {X : Ω → ℝ} {μ : MeasureTheory.Measure Ω} (a : ℝ),\n  (∀ (t : ℝ), a < t → MeasureTheory.Integrable (fun ω => Real.exp (-t * X ω)) μ) →\n    ∀ (s : ℂ), a < s.re → AnalyticAt ℂ (Laplace.transform X μ) s"}
