CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Moebius.LaplaceHolomorphy","name":"GRWTSK.RiemannHypothesis.CCC.signedPickupLaplace_eq_part_difference","type":"Continuous wholePickup →\n  (∀ (σ : ℝ),\n      0 < σ →\n        MeasureTheory.IntegrableOn (fun u => Real.exp (-σ * u) * wholePickup u) (Set.Ioi 0) MeasureTheory.volume) →\n    ∀ {z : ℂ},\n      0 < z.re →\n        Laplace.transform id (pickupPartMeasure 1) z - Laplace.transform id (pickupPartMeasure (-1)) z =\n          signedPickupLaplace z"}
