CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Zeta.Riemann.LaplaceCriterion","name":"GRWTSK.RiemannHypothesis.CCC.regularized_initial_identity_of_inverse","type":"∀ (L : ℂ → ℂ),\n  (∀ (z : ℂ), 1 / 2 < z.re → L z = 1 / (z * (z + 1 / 2) * riemannZeta (z + 1 / 2))) →\n    ∀ (z : ℂ), 1 / 2 < z.re → z * regularizedZeta (z + 1 / 2) * L z = z - 1 / 2"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Zeta.Riemann.LaplaceCriterion","name":"GRWTSK.RiemannHypothesis.CCC.riemannHypothesis_of_holomorphic_laplace","type":"∀ (L : ℂ → ℂ),\n  DifferentiableOn ℂ L pickupLaplaceDomain →\n    (∀ (z : ℂ), 1 / 2 < z.re → z * regularizedZeta (z + 1 / 2) * L z = z - 1 / 2) → RiemannHypothesis"}
CCC_DECL::{"axioms":["propext","Classical.choice","Quot.sound"],"kind":"theorem","module":"GRWTSK.NumberTheory.Zeta.Riemann.LaplaceCriterion","name":"GRWTSK.RiemannHypothesis.CCC.zeta_ne_zero_of_holomorphic_laplace","type":"∀ (L : ℂ → ℂ),\n  DifferentiableOn ℂ L pickupLaplaceDomain →\n    (∀ (z : ℂ), 1 / 2 < z.re → z * regularizedZeta (z + 1 / 2) * L z = z - 1 / 2) →\n      ∀ (s : ℂ), 1 / 2 < s.re → s ≠ 1 → riemannZeta s ≠ 0"}
